import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#game-canvas');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'low-power'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();
const camera=new THREE.OrthographicCamera(-5,5,6,-6,.1,80); camera.position.set(0,0,24); camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xdff7ff,0x75463b,2.1));
const keyLight=new THREE.DirectionalLight(0xfff1cc,2.9); keyLight.position.set(-4,7,12); keyLight.castShadow=true; keyLight.shadow.mapSize.set(1024,1024); scene.add(keyLight);
const fillLight=new THREE.PointLight(0x66d9d4,55,22); fillLight.position.set(5,2,7); scene.add(fillLight);
const backdrop=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshBasicMaterial({map:makeBackdrop()})); backdrop.position.z=-8; scene.add(backdrop);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,.8),new THREE.MeshStandardMaterial({color:0x684331,roughness:.88})); ground.position.set(0,-6.25,-1); ground.receiveShadow=true; scene.add(ground);
const rim=new THREE.Mesh(new THREE.BoxGeometry(200,.12,.2),new THREE.MeshStandardMaterial({color:0xf2bd63,roughness:.7})); rim.position.set(0,-5.84,-.7); scene.add(rim);

function makeBackdrop(){const c=document.createElement('canvas');c.width=512;c.height=512;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,0,512);g.addColorStop(0,'#1c6073');g.addColorStop(.52,'#327e87');g.addColorStop(1,'#183f57');x.fillStyle=g;x.fillRect(0,0,512,512);for(let i=0;i<14;i++){let y=20+i*38;x.fillStyle=i%2?'rgba(255,215,142,.045)':'rgba(5,34,48,.09)';x.fillRect(0,y,512,1);x.fillStyle='rgba(233,194,126,.055)';x.fillRect(0,y+18,512,2)}for(let i=0;i<70;i++){let xx=Math.random()*512,yy=Math.random()*512;x.fillStyle=`rgba(255,245,206,${Math.random()*.045})`;x.beginPath();x.arc(xx,yy,Math.random()*1.7,0,Math.PI*2);x.fill()}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);const vh=5.6,aspect=w/h;camera.left=-vh*aspect;camera.right=vh*aspect;camera.top=vh;camera.bottom=-vh;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();

const FRUITS=[
 {name:'Apple',color:0xe94339,inside:0xffe6a8,sx:.57,sy:.65,sz:.52,points:10,shape:'apple',leaf:0x459443},
 {name:'Peach',color:0xf58a45,inside:0xffdfae,sx:.57,sy:.58,sz:.49,points:12,shape:'peach'},
 {name:'Mango',color:0xffb52e,inside:0xffe08a,sx:.49,sy:.72,sz:.43,points:15,shape:'mango'},
 {name:'Tangerine',color:0xff8a19,inside:0xffd77e,sx:.56,sy:.53,sz:.52,points:10,shape:'tangerine'},
 {name:'Watermelon',color:0x258c50,inside:0xff4b51,sx:.75,sy:.52,sz:.52,points:18,shape:'melon'},
 {name:'Dragon fruit',color:0xe84778,inside:0xfff0de,sx:.61,sy:.57,sz:.49,points:20,shape:'dragon'},
 {name:'Jackfruit',color:0x89a63c,inside:0xffd04c,sx:.62,sy:.75,sz:.55,points:22,shape:'jackfruit'}
];
let brightness=1;
function makeMaterial(color,rough=.42,metal=0){const c=new THREE.Color(color);c.multiplyScalar(brightness);return new THREE.MeshStandardMaterial({color:c,roughness:rough,metalness:metal})}
function shapePoint(v,type){const p=v.clone();const x=p.x,y=p.y,z=p.z; if(type==='apple'){const factor=1-.12*Math.max(0,y)+.035*Math.cos(Math.atan2(z,x)*5)*(Math.max(0,y));p.multiplyScalar(factor);p.y+=.055*Math.max(0,y*y)} if(type==='peach'){p.x*=1+.04*Math.sin(y*4);p.y*=.95} if(type==='mango'){p.x*=.76+.2*((y+1)/2);p.x+=.12*y;p.z*=.88} if(type==='tangerine'){p.y*=.86;p.x*=1+.025*Math.cos(Math.atan2(z,x)*10)} if(type==='melon'){p.x*=1.32;p.y*=.85} if(type==='dragon'){p.x*=1.13;p.y*=.92} if(type==='jackfruit'){p.x*=.83+.18*Math.cos(y*2);p.y*=1.06} return p}
function makeBodyGeometry(type,half=0){const phi=half===0?0:Math.PI;const geom=new THREE.SphereGeometry(1,28,22,phi,Math.PI);const pos=geom.attributes.position;const v=new THREE.Vector3();for(let i=0;i<pos.count;i++){v.fromBufferAttribute(pos,i);const shaped=shapePoint(v,type);pos.setXYZ(i,shaped.x,shaped.y,shaped.z)}pos.needsUpdate=true;geom.computeVertexNormals();return geom}
function addFruitDetail(g,type,def){const skin=makeMaterial(def.color,.38);const stemmat=makeMaterial(0x62402b);const leafmat=makeMaterial(def.leaf||0x4c9d47,.62);const dark=makeMaterial(0x18202b,.85);const white=makeMaterial(0xfaf0d2,.6);const sphere=(geo,mat,pos,scale,rot)=>{let m=new THREE.Mesh(geo,mat);m.position.set(...pos);m.scale.set(...scale);if(rot)m.rotation.set(...rot);m.castShadow=true;g.add(m);return m};
 if(type==='apple'){sphere(new THREE.CylinderGeometry(.025,.038,.16,8),stemmat,[0,.6,0],[1,1,1],[0,0,-.18]);sphere(new THREE.SphereGeometry(.12,12,8),leafmat,[.13,.61,0],[1.35,.35,.55],[0,0,.4])}
 if(type==='peach'){const seam=new THREE.Mesh(new THREE.TorusGeometry(.44,.012,6,36),makeMaterial(0xffc073));seam.rotation.y=Math.PI/2;seam.scale.set(.92,1,1);g.add(seam)}
 if(type==='mango'){sphere(new THREE.CylinderGeometry(.018,.035,.15,8),stemmat,[-.06,.7,0],[1,1,1],[0,0,-.4]);sphere(new THREE.SphereGeometry(.11,12,8),leafmat,[.12,.68,0],[1.4,.28,.7],[0,0,.25])}
 if(type==='tangerine'){sphere(new THREE.CylinderGeometry(.055,.065,.045,10),leafmat,[0,.48,0],[1,1,1]);sphere(new THREE.SphereGeometry(.07,10,7),makeMaterial(0xf2b544),[0,.53,0],[.8,.4,.8])}
 if(type==='melon'){for(let i=-2;i<=2;i++){let stripe=new THREE.Mesh(new THREE.TorusGeometry(.51,.025,6,40),makeMaterial(i%2?0xa9cb5b:0x146f46));stripe.rotation.x=Math.PI/2;stripe.position.x=i*.24;stripe.scale.set(.65,1,1);g.add(stripe)}}
 if(type==='dragon'){for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const leaf=sphere(new THREE.ConeGeometry(.095,.32,6),leafmat,[Math.cos(a)*.38,Math.sin(a)*.28,.08],[.68,1,.65],[0,0,a+Math.PI/2]);leaf.rotation.x=-.45} }
 if(type==='jackfruit'){const bumpmat=makeMaterial(0xa6b84a,.65);for(let i=0;i<18;i++){const y=-.62+(i%6)*.24;const a=Math.floor(i/6)*2.1+(i%2)*.3; sphere(new THREE.SphereGeometry(.075,8,6),bumpmat,[Math.cos(a)*.48,y,Math.sin(a)*.38],[1.2,1.1,.8])}}
 // tiny natural surface highlights add shape identity and soft glossy glints
}
function createFruit(def,index){const g=new THREE.Group();const type=def.shape;const mat=makeMaterial(def.color,.34);let body=new THREE.Mesh(makeBodyGeometry(type),mat);body.scale.set(def.sx,def.sy,def.sz);body.castShadow=true;body.receiveShadow=true;g.add(body);addFruitDetail(g,type,def);
 // The cut face is a real inset disc revealed on both halves.
 const face=new THREE.CircleGeometry(1,32);face.scale(def.sx*.94,def.sy*.94,1);let flesh=new THREE.Mesh(face,makeMaterial(def.inside,.7));flesh.position.z=0;g.add(flesh);
 const seedmat=makeMaterial(type==='melon'?0x33231d:0x28252b,.85);if(type==='melon'||type==='dragon'){for(let i=0;i<9;i++){let a=i*2.4,r=.22+Math.random()*.12;let seed=new THREE.Mesh(new THREE.SphereGeometry(type==='melon'?.025:.014,7,5),seedmat);seed.position.set(Math.cos(a)*def.sx*r,Math.sin(a)*def.sy*r,.014);seed.scale.set(.7,1.5,.4);flesh.add(seed)}}
 g.userData={def,index,body,alive:true,sliced:false,decorative:false,age:0,velocity:new THREE.Vector3(),spin:0};return g;}

const active=[];const debris=[];const decor=[];let state='menu',score=0,best=Number(localStorage.getItem('fruit-best')||0),misses=0,spawnTimer=0,roundTime=0,swipeLast=null,swipeHits=new Set(),comboTimer=0;let viewH=5.6,toastTimer=0;
function updateMenuBest(){document.querySelector('#menu-best').textContent=String(best).padStart(4,'0')}
function clearFruits(){for(const f of [...active,...decor])scene.remove(f);active.length=0;decor.length=0;debris.forEach(d=>scene.remove(d));debris.length=0}
function makeDecor(){clearFruits();for(let i=0;i<6;i++){let d=FRUITS[(i*2)%FRUITS.length],f=createFruit(d,i);f.userData.decorative=true;f.position.set((Math.random()-.5)*8,Math.random()*10-4,-1+Math.random()*1.5);f.rotation.z=Math.random()*6;f.scale.setScalar(.68+Math.random()*.28);scene.add(f);decor.push(f)}}makeDecor();
function startGame(){ensureAudio();playSfx('tap');clearFruits();score=0;misses=0;roundTime=0;spawnTimer=.45;state='playing';document.querySelector('#score').textContent='0';document.querySelector('#lives').textContent='♥ ♥ ♥';document.querySelector('#hud').classList.remove('hidden');hideScreens();setTimeout(()=>{if(state==='playing')spawnWave()},350)}
function hideScreens(){for(const id of ['menu-screen','settings-screen','credits-screen','pause-screen','gameover-screen'])document.getElementById(id).classList.add('hidden')}
function goMenu(){state='menu';document.querySelector('#hud').classList.add('hidden');hideScreens();document.querySelector('#menu-screen').classList.remove('hidden');makeDecor()}
function pauseGame(){if(state!=='playing')return;state='paused';document.querySelector('#pause-screen').classList.remove('hidden')}
function resumeGame(){if(state!=='paused')return;state='playing';document.querySelector('#pause-screen').classList.add('hidden');ensureAudio()}
function gameOver(){if(state!=='playing')return;state='over';const wasBest=score>best;if(wasBest){best=score;localStorage.setItem('fruit-best',String(best))}document.querySelector('#final-score').textContent=score;document.querySelector('#final-best').textContent=best+(wasBest?'  ✦ NEW!':'');updateMenuBest();document.querySelector('#hud').classList.add('hidden');document.querySelector('#gameover-screen').classList.remove('hidden');playSfx('over')}
function fruitIndex(){let unlocked=1+Math.min(6,Math.floor(score/60));return Math.floor(Math.random()*unlocked)}
function spawnWave(){if(state!=='playing')return;const count=Math.random()<Math.min(.62,.16+score/500)?2+(Math.random()<.25?1:0):1;const positions=[];for(let i=0;i<count;i++){const idx=fruitIndex(),def=FRUITS[idx],x=(Math.random()-.5)*Math.min(7.5,viewH*innerWidth/innerHeight*1.35);const f=createFruit(def,idx);f.position.set(x,-6.3,-.4+Math.random()*1.6);f.rotation.z=(Math.random()-.5)*.8;f.userData.velocity.set((Math.random()-.5)*2.4,8.5+Math.random()*2.2,0);f.userData.spin=(Math.random()-.5)*2.3;f.userData.age=0;scene.add(f);active.push(f);positions.push(f)}playSfx('launch');}
function missFruit(f){if(f.userData.sliced||!f.userData.alive)return;f.userData.alive=false;scene.remove(f);let i=active.indexOf(f);if(i>=0)active.splice(i,1);misses++;const hearts=3-misses;document.querySelector('#lives').textContent='♥ '.repeat(Math.max(0,hearts)).trim()||'♡';if(misses>=3)gameOver()}
function projectPointer(e){const rect=canvas.getBoundingClientRect();const ndc=new THREE.Vector3((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height)*2+1,.5);ndc.unproject(camera);const dir=ndc.sub(camera.position).normalize();const t=-camera.position.z/dir.z;return new THREE.Vector2(camera.position.x+dir.x*t,camera.position.y+dir.y*t)}
function segmentDist(p,a,b){const ab=b.clone().sub(a);const l=ab.lengthSq();if(!l)return p.distanceTo(a);const t=THREE.MathUtils.clamp(p.clone().sub(a).dot(ab)/l,0,1);return p.distanceTo(a.clone().add(ab.multiplyScalar(t)))}
function onPointerDown(e){if(state!=='playing')return;ensureAudio();canvas.setPointerCapture?.(e.pointerId);swipeLast=projectPointer(e);swipeHits=new Set();drawTrail(e.clientX,e.clientY,e.clientX+1,e.clientY+1)}
function onPointerMove(e){if(!swipeLast||state!=='playing')return;const p=projectPointer(e);sliceSegment(swipeLast,p);const rect=canvas.getBoundingClientRect();drawTrail(e.clientX,e.clientY,e.clientX-(swipeScreenX||e.clientX),e.clientY-(swipeScreenY||e.clientY));swipeScreenX=e.clientX;swipeScreenY=e.clientY;swipeLast=p}
let swipeScreenX=0,swipeScreenY=0;
function drawTrail(x,y,dx,dy){if(Math.hypot(dx,dy)<2)return;const t=document.createElement('i');t.className='trail';t.style.left=(x-dx)+'px';t.style.top=(y-dy)+'px';t.style.width=Math.hypot(dx,dy)+'px';t.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;document.body.appendChild(t);setTimeout(()=>t.remove(),130)}
function onPointerUp(){swipeLast=null;swipeHits.clear()}
canvas.addEventListener('pointerdown',onPointerDown);canvas.addEventListener('pointermove',onPointerMove);canvas.addEventListener('pointerup',onPointerUp);canvas.addEventListener('pointercancel',onPointerUp);
function sliceSegment(a,b){if(a.distanceTo(b)<.04)return;for(const f of [...active]){if(!f.userData.alive||f.userData.sliced||swipeHits.has(f))continue;const center=new THREE.Vector2(f.position.x,f.position.y);const radius=Math.max(f.userData.def.sx,f.userData.def.sy)*.87;if(segmentDist(center,a,b)<radius){swipeHits.add(f);sliceFruit(f,a,b)}}}
function sliceFruit(f,a,b){const u=f.userData;u.sliced=true;u.alive=false;const d=u.def;const points=d.points;score+=points;for(const other of active){if(other!==f&&!other.userData.sliced&&segmentDist(new THREE.Vector2(other.position.x,other.position.y),a,b)<Math.max(other.userData.def.sx,other.userData.def.sy)*.87){swipeHits.add(other);sliceFruit(other,a,b)}}
 document.querySelector('#score').textContent=score;const scoreEl=document.querySelector('.score-label strong');scoreEl.classList.remove('fruit-pop');void scoreEl.offsetWidth;scoreEl.classList.add('fruit-pop');
 const index=active.indexOf(f);if(index>=0)active.splice(index,1);scene.remove(f);spawnHalves(f);juice(f.position,d.color);playSfx('slice');playSfx('score');showPoints(f.position,points);if(swipeHits.size>=2){const bonus=(swipeHits.size-1)*5;score+=bonus;document.querySelector('#score').textContent=score;showCombo(swipeHits.size,bonus);playSfx('combo')}
}
function spawnHalves(f){const u=f.userData,d=u.def;const base=f.position;for(let side=0;side<2;side++){const g=new THREE.Group();const geom=makeBodyGeometry(d.shape,side);const mat=makeMaterial(d.color,.37);const shell=new THREE.Mesh(geom,mat);shell.scale.set(d.sx,d.sy,d.sz);shell.castShadow=true;g.add(shell);const face=new THREE.Mesh(new THREE.CircleGeometry(1,24),makeMaterial(d.inside,.74));face.scale.set(d.sx*.95,d.sy*.95,1);face.position.z=side===0?.008:-.008;if(side===1)face.rotation.y=Math.PI;g.add(face);if(d.shape==='melon'||d.shape==='dragon'){for(let j=0;j<7;j++){const seed=new THREE.Mesh(new THREE.SphereGeometry(.018,6,5),makeMaterial(d.shape==='melon'?0x302019:0x25212b));seed.position.set((Math.random()-.5)*d.sx*.8,(Math.random()-.5)*d.sy*.8,side===0?.025:-.025);g.add(seed)}}g.position.copy(base);g.rotation.copy(f.rotation);g.position.z=base.z+(side?-.06:.06);const dir=side?-1:1;g.userData={vy:u.velocity.y*.28, vx:u.velocity.x*.25+dir*(1.7+Math.random()), spin:u.spin+dir*(2.5+Math.random()*2),age:0};scene.add(g);debris.push(g)} }
function juice(pos,color){for(let i=0;i<13;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.035,7,6),makeMaterial(color,.28));m.position.copy(pos);m.position.z+=.25+Math.random()*.5;m.userData={vx:(Math.random()-.5)*5,vy:(Math.random()-.25)*5,life:.45+Math.random()*.45};scene.add(m);debris.push(m)}}
function showPoints(pos,n){const p=document.createElement('div');p.className='toast';p.textContent=`+${n}`;p.style.bottom='auto';p.style.left=`${(pos.x/(viewH*innerWidth/innerHeight)+1)*50}%`;p.style.top=`${(1-pos.y/viewH)*50}%`;p.style.color='#fff18a';p.style.borderColor='#fff18a';p.style.opacity='.94';document.querySelector('#game-shell').appendChild(p);setTimeout(()=>p.remove(),600)}
function showCombo(n,b){const el=document.querySelector('#combo');el.textContent=`${n} FRUIT COMBO! +${b}`;el.classList.remove('hidden');el.style.animation='none';void el.offsetWidth;el.style.animation='';setTimeout(()=>el.classList.add('hidden'),700)}

