const seedmat=makeMaterial(type==='melon'?0x33231d:0x28252b,.85);if(type==='melon'||type==='dragon'){for(let i=0;i<9;i++){let a=i*2.4,r=.22+Math.random()*.12;let seed=new THREE.Mesh(new THREE.SphereGeometry(type==='melon'?.025:.014,7,5),seedmat);seed.position.set(Math.cos(a)*def.sx*r,Math.sin(a)*def.sy*r,.014);seed.scale.set(.7,1.5,.4);flesh.add(seed)}}

