// Small synthesized audio keeps the game self-contained and works after the first tap.
let audio=null,musicTimer=null,musicStep=0;const audioSettings=loadSettings();
function loadSettings(){try{return{master:.72,sfx:.75,music:.38,brightness:1,musicOn:true,muted:false,...JSON.parse(localStorage.getItem('fruit-settings')||'{}')}}catch{return{master:.72,sfx:.75,music:.38,brightness:1,musicOn:true,muted:false}}}
function saveSettings(){localStorage.setItem('fruit-settings',JSON.stringify(audioSettings))}
function ensureAudio(){if(!audio){const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;audio=new Ctx();}if(audio.state==='suspended')audio.resume();if(audioSettings.musicOn&&!musicTimer)startMusic()}
function volume(kind){return (audioSettings.muted?0:audioSettings.master)*(kind==='music'?audioSettings.music:audioSettings.sfx)}
function tone(freq,duration,wave='sine',gain=.08,delay=0){if(!audio)return;const now=audio.currentTime+delay,osc=audio.createOscillator(),amp=audio.createGain();osc.type=wave;osc.frequency.setValueAtTime(freq,now);amp.gain.setValueAtTime(.0001,now);amp.gain.exponentialRampToValueAtTime(Math.max(.0002,gain*volume('sfx')),now+.012);amp.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(amp);amp.connect(audio.destination);osc.start(now);osc.stop(now+duration+.03)}
function playSfx(kind){if(!audio) return;if(kind==='tap'){tone(620,.07,'sine',.04);return}if(kind==='launch'){tone(310,.09,'triangle',.025);return}if(kind==='slice'){tone(850,.08,'sawtooth',.045);tone(1250,.12,'sine',.03,.025);return}if(kind==='score'){tone(740,.1,'sine',.04);return}if(kind==='combo'){tone(660,.13,'triangle',.06);tone(990,.2,'triangle',.05,.09);return}if(kind==='over'){tone(400,.2,'triangle',.05);tone(300,.32,'triangle',.04,.18)}}
const melody=[523,659,784,659,587,698,880,698,523,659,784,988,880,784,659,587];
function startMusic(){if(!audio||musicTimer||!audioSettings.musicOn)return;musicTimer=setInterval(()=>{if(!audio||state==='paused')return;const f=melody[musicStep++%melody.length];const now=audio.currentTime,osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,.025*volume('music')),now+.08);gain.gain.exponentialRampToValueAtTime(.0001,now+.36);osc.connect(gain);gain.connect(audio.destination);osc.start(now);osc.stop(now+.38);},330)}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}}
function setBrightness(value){brightness=Number(value);scene.traverse(o=>{if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];for(const m of mats){if(m.userData?.baseColor){m.color.copy(m.userData.baseColor).multiplyScalar(brightness);m.needsUpdate=true}}}})}
// Remember original material color so the brightness slider updates existing and future fruit.
const rawMakeMaterial=makeMaterial;
// Replace the factory with a version that retains a stable base color for live adjustment.
