// Self-contained synthesized effects and a gentle looping arpeggio; audio starts on the first user gesture.
let audio=null,musicTimer=null,musicStep=0;
function loadSettings(){try{return{master:.72,sfx:.75,music:.38,brightness:1,musicOn:true,muted:false,...JSON.parse(localStorage.getItem('fruit-settings')||'{}')}}catch{return{master:.72,sfx:.75,music:.38,brightness:1,musicOn:true,muted:false}}}
const audioSettings=loadSettings();
function saveSettings(){try{localStorage.setItem('fruit-settings',JSON.stringify(audioSettings))}catch{}}
function ensureAudio(){if(!audio){const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;audio=new Ctx()}if(audio.state==='suspended')audio.resume();if(audioSettings.musicOn&&!musicTimer)startMusic()}
function volume(kind){return(audioSettings.muted?0:audioSettings.master)*(kind==='music'?audioSettings.music:audioSettings.sfx)}
function tone(freq,duration,wave='sine',gain=.08,delay=0){if(!audio)return;const now=audio.currentTime+delay,osc=audio.createOscillator(),amp=audio.createGain();osc.type=wave;osc.frequency.setValueAtTime(freq,now);amp.gain.setValueAtTime(.0001,now);amp.gain.exponentialRampToValueAtTime(Math.max(.0002,gain*volume('sfx')),now+.012);amp.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(amp);amp.connect(audio.destination);osc.start(now);osc.stop(now+duration+.03)}
function playSfx(kind){if(!audio)return;if(kind==='tap'){tone(620,.07,'sine',.04);return}if(kind==='launch'){tone(310,.09,'triangle',.025);return}if(kind==='slice'){tone(850,.08,'sawtooth',.045);tone(1250,.12,'sine',.03,.025);return}if(kind==='score'){tone(740,.1,'sine',.04);return}if(kind==='combo'){tone(660,.13,'triangle',.06);tone(990,.2,'triangle',.05,.09);return}if(kind==='over'){tone(400,.2,'triangle',.05);tone(300,.32,'triangle',.04,.18)}}
const melody=[523,659,784,659,587,698,880,698,523,659,784,988,880,784,659,587];
function startMusic(){if(!audio||musicTimer||!audioSettings.musicOn)return;musicTimer=setInterval(()=>{if(!audio)return;const f=melody[musicStep++%melody.length],now=audio.currentTime,osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,.025*volume('music')),now+.08);gain.gain.exponentialRampToValueAtTime(.0001,now+.36);osc.connect(gain);gain.connect(audio.destination);osc.start(now);osc.stop(now+.38)},330)}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}}
function syncSettingsUI(){for(const[id,key]of[['master-volume','master'],['sfx-volume','sfx'],['music-volume','music'],['brightness','brightness']])document.getElementById(id).value=audioSettings[key];for(const[id,key]of[['master-value','master'],['sfx-value','sfx'],['music-value','music']])document.getElementById(id).textContent=Math.round(audioSettings[key]*100)+'%';document.getElementById('brightness-value').textContent=Math.round(audioSettings.brightness*100)+'%';document.querySelector('#music-switch span').textContent=audioSettings.musicOn?'ON':'OFF';document.querySelector('#sound-toggle').textContent=audioSettings.muted?'♫̸':'♫';brightness=audioSettings.brightness;scene.traverse(o=>{if(!o.material)return;const ms=Array.isArray(o.material)?o.material:[o.material];for(const m of ms)if(m.userData.baseColor)m.color.copy(m.userData.baseColor).multiplyScalar(brightness)})}
for(const[id,key]of[['master-volume','master'],['sfx-volume','sfx'],['music-volume','music'],['brightness','brightness']])document.getElementById(id).addEventListener('input',e=>{audioSettings[key]=Number(e.target.value);saveSettings();syncSettingsUI()});
document.querySelector('#music-switch').addEventListener('click',()=>{audioSettings.musicOn=!audioSettings.musicOn;if(audioSettings.musicOn){ensureAudio();startMusic()}else stopMusic();saveSettings();syncSettingsUI();playSfx('tap')});
document.querySelector('#sound-toggle').addEventListener('click',()=>{audioSettings.muted=!audioSettings.muted;saveSettings();syncSettingsUI();if(!audioSettings.muted)ensureAudio()});
function clickSound(){ensureAudio();playSfx('tap')}
document.querySelector('#play-button').addEventListener('click',startGame);
document.querySelector('#settings-button').addEventListener('click',()=>{clickSound();hideScreens();document.querySelector('#settings-screen').classList.remove('hidden');syncSettingsUI()});
document.querySelector('#credits-button').addEventListener('click',()=>{clickSound();hideScreens();document.querySelector('#credits-screen').classList.remove('hidden')});
document.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',()=>{clickSound();hideScreens();document.getElementById(b.dataset.back).classList.remove('hidden')}));
document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{clickSound();goMenu()}));
document.querySelector('#pause-button').addEventListener('click',()=>{playSfx('tap');pauseGame()});
document.querySelector('#resume-button').addEventListener('click',()=>{playSfx('tap');resumeGame()});
document.querySelector('#restart-button').addEventListener('click',startGame);
document.querySelector('#again-button').addEventListener('click',startGame);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame()});
syncSettingsUI();updateMenuBest();
let lastTime=performance.now();
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.035,(now-lastTime)/1000);lastTime=now;const elapsed=now/1000;
 if(state==='playing'){roundTime+=dt;spawnTimer-=dt;if(spawnTimer<=0){spawnWave();spawnTimer=Math.max(.72,1.65-roundTime*.009-score*.0008)+Math.random()*.38}for(const f of [...active]){const u=f.userData;u.age+=dt;u.velocity.y-=9.5*dt;f.position.addScaledVector(u.velocity,dt);f.rotation.z+=u.spin*dt;f.rotation.x+=dt*.32;if(f.position.y< -6.5)missFruit(f)}}
 for(const f of decor){f.position.y+=Math.sin(elapsed*.7+f.userData.index)*dt*.32;f.position.x+=Math.cos(elapsed*.45+f.userData.index)*dt*.15;f.rotation.z+=dt*.18;f.rotation.y+=dt*.22}
 for(let i=debris.length-1;i>=0;i--){const o=debris[i],u=o.userData;if(u.life!==undefined){u.life-=dt;u.vy-=5*dt;o.position.x+=u.vx*dt;o.position.y+=u.vy*dt;o.scale.multiplyScalar(Math.max(.01,1-dt*1.1));if(u.life<=0){scene.remove(o);debris.splice(i,1)}}else{u.age+=dt;u.vy-=8.8*dt;o.position.x+=u.vx*dt;o.position.y+=u.vy*dt;o.rotation.z+=u.spin*dt;if(u.age>1.8||o.position.y< -7){scene.remove(o);debris.splice(i,1)}}}
 renderer.render(scene,camera)}
requestAnimationFrame(animate);

