*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
 :root{font-family:'Nunito',system-ui,sans-serif;color:#fff4d6;--cream:#fff2cf;--gold:#ffce58;--ink:#14354a;--wood:#8b4e29}
html,body{height:100%;margin:0;overflow:hidden;background:#102b41}
body{touch-action:none}
button,input{font:inherit}
button{cursor:pointer;color:inherit}
#game-shell{position:relative;width:100%;height:100dvh;min-height:460px;overflow:hidden;background:radial-gradient(ellipse at 50% 40%,#4b92a1 0,#246174 38%,#123b54 78%,#09283e 100%);isolation:isolate}
#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(6,29,44,.3),transparent 25%,transparent 65%,rgba(5,25,40,.44));z-index:1}
.topbar{position:absolute;z-index:5;left:0;right:0;top:0;padding:calc(12px + env(safe-area-inset-top)) 18px 10px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}
.brand-mark{font:800 17px 'Baloo 2',sans-serif;letter-spacing:1.6px;color:#ffe7a4;text-shadow:0 2px 3px #552c1d}
.brand-mark small{font-size:11px;background:#ed6840;color:white;border-radius:4px;padding:1px 4px;vertical-align:2px}
.brand-fruit{color:#ff735d}
.icon-btn{pointer-events:auto;border:2px solid rgba(255,244,214,.7);background:rgba(13,49,66,.66);box-shadow:0 3px 0 rgba(5,29,41,.5);width:43px;height:43px;border-radius:14px;font-size:23px;font-weight:900}
.hud{position:absolute;z-index:4;top:calc(67px + env(safe-area-inset-top));left:17px;right:17px;display:flex;align-items:center;justify-content:space-between;pointer-events:none}
.hud>*{pointer-events:auto}
.score-label{font:800 12px 'Baloo 2';letter-spacing:1.3px;color:#ffefc7;text-shadow:0 2px 2px #12354b}
.score-label strong{display:block;font:800 32px 'Baloo 2';letter-spacing:0;line-height:1;text-shadow:0 3px 1px #8e3d25}
.lives{font-size:20px;letter-spacing:3px;color:#ff725f;text-shadow:0 2px 3px #662a29}
.pause-btn{font-size:20px;width:42px;height:42px}
.screen{position:absolute;z-index:3;inset:0;display:flex;align-items:center;justify-content:center;text-align:center}
.hidden{display:none!important}
.menu-screen{flex-direction:column;padding:75px 20px 24px}
.floating-tag{font:700 13px 'Baloo 2';letter-spacing:.6px;color:#d4ffdc;background:rgba(18,73,76,.58);border:1px solid rgba(216,255,213,.4);border-radius:20px;padding:6px 15px;box-shadow:0 3px 0 rgba(4,38,47,.3);transform:rotate(-3deg);margin-bottom:5px}
.logo{position:relative;font:800 clamp(66px,15vw,108px)/.72 'Baloo 2',sans-serif;letter-spacing:-5px;margin:17px 0 10px;color:#ffce52;text-shadow:0 4px 0 #f18a35,0 8px 0 #ba4d30,0 12px 0 #743b31,0 16px 16px rgba(8,27,42,.65);transform:rotate(-3deg)}
.logo span{color:#fff3ce}
.logo em{position:absolute;font:800 26px 'Baloo 2';letter-spacing:1px;color:#fff;background:#eb5f4b;border:3px solid #fff0c7;border-radius:12px;padding:3px 10px;right:-39px;bottom:2px;transform:rotate(9deg);box-shadow:0 3px 0 #9c3e32}
.tagline{font:700 18px 'Baloo 2';letter-spacing:1px;margin:15px 0 14px;color:#fff2d6;text-shadow:0 2px 4px #184253}
.menu-buttons{width:min(270px,78vw);display:grid;gap:10px}
.wood-button{border:3px solid #ffdc92;background:linear-gradient(#bf7940,#98502c);color:#fff4d3;border-radius:16px;box-shadow:0 5px 0 #5c352b,0 8px 10px rgba(0,0,0,.25),inset 0 2px 0 rgba(255,255,255,.25);font:800 18px 'Baloo 2';letter-spacing:1.2px;text-shadow:0 2px 0 #77402a;padding:10px 20px;transition:transform .12s,filter .12s;min-height:49px}
.wood-button span{float:right;color:#ffd56f;font-size:19px}
.wood-button:active{transform:translateY(3px) scale(.98);filter:brightness(1.12);box-shadow:0 2px 0 #5c352b}
.wood-button.primary{background:linear-gradient(#ffbd43,#ee753b);border-color:#fff0aa;color:#fffbe8;font-size:22px;min-height:57px;box-shadow:0 5px 0 #a74431,0 8px 10px rgba(0,0,0,.25),inset 0 2px 0 rgba(255,255,255,.36)}
.text-button{border:0;background:transparent;color:#ffe9b8;font:800 13px 'Baloo 2';letter-spacing:2px;text-shadow:0 2px 3px #173a4a;padding:10px}
.best-pill{margin-top:14px;background:rgba(9,43,59,.55);border:1px solid rgba(255,232,179,.35);padding:5px 14px;border-radius:20px;font:700 11px 'Baloo 2';letter-spacing:1px;color:#fce6b6}
.best-pill b{color:#fff;font-size:14px;margin-left:8px}
.hint{position:absolute;bottom:calc(15px + env(safe-area-inset-bottom));font:700 10px 'Baloo 2';letter-spacing:1.5px;color:rgba(238,255,229,.76)}
.panel-screen{padding:70px 16px 18px;background:rgba(6,31,46,.3);backdrop-filter:blur(3px)}
.panel-card{position:relative;width:min(410px,100%);max-height:calc(100dvh - 100px);overflow:auto;border:4px solid #f8d895;border-radius:25px;padding:28px 25px 22px;background:linear-gradient(155deg,rgba(42,105,113,.96),rgba(17,61,79,.97));box-shadow:0 12px 0 rgba(8,37,48,.65),0 25px 40px rgba(0,0,0,.3),inset 0 2px 0 rgba(255,255,255,.18)}
.panel-card h2{font:800 34px 'Baloo 2';line-height:1;margin:7px 0;color:#ffdb75;text-shadow:0 3px 0 #873f30}
.panel-subtitle{margin:0 0 22px;font:600 14px 'Nunito';color:#e4f2dc}
.back-button{position:absolute;top:14px;left:16px;border:0;background:transparent;color:#e9f4dc;font:800 12px 'Baloo 2';letter-spacing:1px;padding:5px}
.setting-row{display:grid;grid-template-columns:1fr 34px;gap:5px 12px;align-items:center;text-align:left;margin:13px 0;font:700 14px 'Nunito'}
.setting-row b{grid-column:2;grid-row:1;color:#ffdc7f;font-size:12px;text-align:right}
.setting-row input{grid-column:1/3;grid-row:2;width:100%;height:24px;accent-color:#ffc754}
.toggle-button{width:100%;margin-top:12px}
.tiny-note{font-size:11px;color:#c7e0d9;margin:15px 0 0}
.credits-card{line-height:1.6}
.credits-card p{color:#e3f1df}
.fruit-roster{font:700 17px/2 'Baloo 2';color:#fff0c5;margin:20px 0}
.fruit-roster span{font-size:13px}
.credits-card .wood-button{width:100%;margin-top:5px}
.compact-card{width:min(350px,100%);padding:32px 26px 23px}
.compact-card .wood-button{width:100%;margin-top:12px}
.compact-card .text-button{margin-top:8px}
.pause-stamp{display:inline-block;background:#ec7347;color:#fff8d8;border:2px solid #ffd891;border-radius:20px;padding:4px 13px;font:800 12px 'Baloo 2';letter-spacing:1px;transform:rotate(-4deg);box-shadow:0 3px 0 #743c34}
.compact-card h2{margin:12px 0 17px}
.final-score-label{font:800 12px 'Baloo 2';letter-spacing:1px;color:#ffefcb}
.final-score-label strong{display:block;color:white;font:800 56px/1 'Baloo 2';text-shadow:0 4px 0 #e46b42}
.best-score-line{margin:10px 0 8px;font:700 12px 'Baloo 2';letter-spacing:1px;color:#d5eee0}
.best-score-line b{color:#ffda76;font-size:16px;margin-left:6px}
.combo{position:absolute;z-index:4;left:50%;top:27%;transform:translate(-50%,-50%) rotate(-7deg);color:#fff36c;font:800 32px 'Baloo 2';text-shadow:0 3px 0 #b9442f,0 6px 8px #082a3a;pointer-events:none;animation:combo-pop .65s ease-out forwards}
@keyframes combo-pop{0%{opacity:0;scale:.5}
20%{opacity:1;scale:1.15}
80%{opacity:1}
100%{opacity:0;translate:0 -32px}
}
.toast{position:absolute;z-index:6;left:50%;bottom:calc(26px + env(safe-area-inset-bottom));transform:translateX(-50%);background:#143f50;border:2px solid #f9d991;border-radius:20px;padding:9px 16px;white-space:nowrap;font:700 13px 'Baloo 2';box-shadow:0 4px 8px #061d2a}
.trail{position:fixed;z-index:8;pointer-events:none;border-radius:20px;height:5px;transform-origin:left center;background:linear-gradient(90deg,rgba(255,255,255,.1),#fffde4,#a8fff1);box-shadow:0 0 8px #fff,0 0 17px #9affec}
.fruit-pop{animation:score-pop .25s ease-out}
@keyframes score-pop{50%{transform:scale(1.35);color:#fff18b}
}
@media(max-height:650px){.menu-screen{padding-top:59px}
.logo{font-size:70px;margin:11px 0 5px}
.tagline{margin:10px 0}
.menu-buttons{gap:7px}
.wood-button{min-height:43px;padding:7px 16px}
.wood-button.primary{min-height:49px}
.best-pill{margin-top:10px}
.hint{bottom:8px}
.panel-card{padding-top:25px;padding-bottom:15px}
.setting-row{margin:8px 0}
}
@media(min-width:700px){.menu-screen{padding-top:75px}
.logo{font-size:112px}
.menu-buttons{width:300px}
.hud{left:30px;right:30px}
}

