import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas = document.querySelector('#game-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'low-power' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
const scene = new THREE.Scene();
const camera = new THREE.OrthographicCamera(-5, 5, 6, -6, .1, 80);
camera.position.set(0, 0, 24);
camera.lookAt(0, 0, 0);
scene.add(new THREE.HemisphereLight(0xe4f8ff, 0x68423a, 2.2));
const keyLight = new THREE.DirectionalLight(0xfff0ce, 2.8);
keyLight.position.set(-4, 7, 12);
scene.add(keyLight);
const fillLight = new THREE.PointLight(0x66d9d4, 35, 24);
fillLight.position.set(5, 2, 8);
scene.add(fillLight);

const fruitTypes = [
  { name: 'Apple', color: 0xe94e43, inside: 0xffe6a3, shape: [1, 1, .9], leaf: 0x62a944 },
  { name: 'Peach', color: 0xf6a06f, inside: 0xffdfad, shape: [1, .94, .9], leaf: 0x62994a },
  { name: 'Mango', color: 0xf6bb37, inside: 0xffe28a, shape: [.83, 1.12, .83], leaf: 0x4d8c43 },
  { name: 'Tangerine', color: 0xff9b32, inside: 0xffd065, shape: [1, .9, .92], leaf: 0x558d39 },
  { name: 'Watermelon', color: 0x3eaa62, inside: 0xff5470, shape: [1.12, .9, .86], leaf: 0x348b4d },
  { name: 'Dragon fruit', color: 0xe94e91, inside: 0xfff0de, shape: [.95, 1.05, .86], leaf: 0x79b95a },
  { name: 'Jackfruit', color: 0x86a944, inside: 0xffd55b, shape: [.82, 1.12, .82], leaf: 0x4d803b }
];
let brightness = 1;
function material(color, roughness = .52) {
  const mat = new THREE.MeshStandardMaterial({ color, roughness, metalness: 0 });
  mat.userData.baseColor = new THREE.Color(color);
  return mat;
}
function addMesh(parent, geometry, mat, position, scale, rotation) {
  const mesh = new THREE.Mesh(geometry, mat);
  if (position) mesh.position.set(...position);
  if (scale) mesh.scale.set(...scale);
  if (rotation) mesh.rotation.set(...rotation);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}
function createFruit(typeIndex, decorative = false) {
  const type = fruitTypes[typeIndex];
  const group = new THREE.Group();
  const base = material(type.color);
  const flesh = material(type.inside, .68);
  const leaf = material(type.leaf, .62);
  const fruitScale = decorative ? .43 : .72;
  let body = addMesh(group, new THREE.SphereGeometry(.66, 24, 18), base, [0, 0, 0], type.shape);
  body.name = 'fruit-body';
  if (typeIndex === 4) {
    const stripeMat = material(0x267d4c);
    for (let i = -2; i <= 2; i++) {
      const stripe = addMesh(group, new THREE.TorusGeometry(.655, .025, 5, 28), stripeMat, [i * .22, 0, 0], [1.05, .88, 1]);
      stripe.rotation.y = Math.PI / 2;
    }
  } else if (typeIndex === 3) {
    for (let i = 0; i < 8; i++) {
      const segment = addMesh(group, new THREE.SphereGeometry(.055, 8, 6), material(0xffc15c), [Math.cos(i * Math.PI / 4) * .22, Math.sin(i * Math.PI / 4) * .25, .48]);
      segment.scale.set(.55, 1, .35);
    }
  } else if (typeIndex === 5) {
    for (let i = 0; i < 6; i++) {
      const angle = i * Math.PI / 3;
      addMesh(group, new THREE.ConeGeometry(.12, .38, 5), leaf, [Math.cos(angle) * .48, Math.sin(angle) * .5, 0], null, [Math.sin(angle) * .8, 0, -Math.cos(angle) * .8]);
    }
  } else if (typeIndex === 6) {
    for (let i = 0; i < 5; i++) {
      const thorn = addMesh(group, new THREE.ConeGeometry(.07, .16, 5), material(0xc9d56a), [Math.cos(i * 1.25) * .55, Math.sin(i * 1.25) * .52, .12]);
      thorn.rotation.z = i * 1.1;
    }
  } else {
    addMesh(group, new THREE.CylinderGeometry(.035, .055, .24, 8), material(0x79502e), [0, .66, 0]);
    const leafMesh = addMesh(group, new THREE.SphereGeometry(.17, 10, 7), leaf, [.14, .72, 0], [1, .38, .52]);
    leafMesh.rotation.z = -.45;
  }
  group.scale.setScalar(fruitScale);
  group.userData.typeIndex = typeIndex;
  group.userData.radius = decorative ? .48 : .76;
  group.userData.isFruit = true;
  return group;
}

// Soft, drifting orchard lights keep the play field lively without obscuring fruit.
const decor = [];
for (let i = 0; i < 12; i++) {
  const glow = new THREE.Mesh(new THREE.SphereGeometry(.06 + Math.random() * .1, 8, 6), new THREE.MeshBasicMaterial({ color: i % 2 ? 0xb8ffdc : 0xffe29a, transparent: true, opacity: .25 }));
  glow.position.set((Math.random() - .5) * 11, (Math.random() - .5) * 11, -2);
  glow.userData.index = i;
  scene.add(glow);
  decor.push(glow);
}

let state = 'menu';
let score = 0;
let bestScore = 0;
let lives = 3;
let roundTime = 0;
let spawnTimer = 0;
let lastSliceTime = 0;
let comboCount = 0;
const active = [];
const debris = [];
let pointerDown = false;
let previousPoint = null;
let toastTimer = 0;
let comboTimer = 0;

function resize() {
  const width = Math.max(1, canvas.clientWidth);
  const height = Math.max(1, canvas.clientHeight);
  renderer.setSize(width, height, false);
  const halfHeight = 6;
  const halfWidth = halfHeight * width / height;
  camera.left = -halfWidth;
  camera.right = halfWidth;
  camera.top = halfHeight;
  camera.bottom = -halfHeight;
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize);
resize();

function loadBest() {
  try { bestScore = Number(localStorage.getItem('fruit-best') || 0) || 0; } catch { bestScore = 0; }
}
function updateMenuBest() { document.querySelector('#menu-best').textContent = String(bestScore).padStart(4, '0'); }
function hideScreens() { document.querySelectorAll('.screen').forEach(el => el.classList.add('hidden')); }
function clearObjects(list) { for (const object of list) scene.remove(object); list.length = 0; }
function setScore(value) {
  score = value;
  document.querySelector('#score').textContent = String(score);
  const scoreEl = document.querySelector('#score');
  scoreEl.classList.remove('fruit-pop');
  void scoreEl.offsetWidth;
  scoreEl.classList.add('fruit-pop');
}
function showToast(message) {
  const toast = document.querySelector('#toast');
  toast.textContent = message;
  toast.classList.remove('hidden');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.add('hidden'), 1500);
}
function updateLives() {
  document.querySelector('#lives').textContent = '♥ '.repeat(lives).trim() + '♡ '.repeat(3 - lives).trim();
}

function spawnFruit(typeIndex = Math.floor(Math.random() * fruitTypes.length), x, y, vx, vy) {
  const fruit = createFruit(typeIndex);
  fruit.position.set(x, y, 0);
  fruit.userData.velocity = new THREE.Vector2(vx, vy);
  fruit.userData.spin = (Math.random() - .5) * 2.4;
  fruit.userData.age = 0;
  active.push(fruit);
  scene.add(fruit);
  return fruit;
}
function spawnWave() {
  const count = 1 + (Math.random() < Math.min(.62, .2 + roundTime / 100) ? 1 : 0) + (roundTime > 38 && Math.random() < .18 ? 1 : 0);
  const center = (Math.random() - .5) * 3.5;
  for (let i = 0; i < count; i++) {
    const x = center + (i - (count - 1) / 2) * 1.65;
    const y = -6.4 - Math.random() * .7;
    const vx = (Math.random() - .5) * 2.1 + (x > 0 ? -.38 : .38);
    const vy = 8.3 + Math.random() * 2.1 + Math.min(1.7, roundTime * .018);
    spawnFruit(Math.floor(Math.random() * fruitTypes.length), x, y, vx, vy);
  }
  if (Math.random() < .24) playSfx('launch');
}
function removeFruit(fruit) {
  const index = active.indexOf(fruit);
  if (index !== -1) active.splice(index, 1);
  scene.remove(fruit);
}
function emitParticles(position, color) {
  const mat = new THREE.MeshBasicMaterial({ color });
  for (let i = 0; i < 10; i++) {
    const bit = new THREE.Mesh(new THREE.SphereGeometry(.035 + Math.random() * .045, 6, 5), mat);
    bit.position.copy(position);
    bit.userData = { life: .45 + Math.random() * .3, vx: (Math.random() - .5) * 5, vy: (Math.random() - .2) * 5 };
    debris.push(bit);
    scene.add(bit);
  }
}
function splitFruit(fruit, direction) {
  const typeIndex = fruit.userData.typeIndex;
  const type = fruitTypes[typeIndex];
  const originalPosition = fruit.position.clone();
  const angle = Math.atan2(direction.y, direction.x);
  removeFruit(fruit);
  for (let side of [-1, 1]) {
    const half = new THREE.Group();
    const outer = material(type.color);
    const inner = material(type.inside, .72);
    const outerMesh = addMesh(half, new THREE.SphereGeometry(.66, 20, 16, side < 0 ? 0 : Math.PI, Math.PI), outer, [side * .12, 0, 0], [type.shape[0], type.shape[1], type.shape[2]]);
    outerMesh.rotation.z = angle;
    const cut = addMesh(half, new THREE.CircleGeometry(.65, 24), inner, [-side * .11, 0, .48], [1, 1, .2]);
    cut.rotation.z = angle;
    half.position.copy(originalPosition);
    half.position.z = .5;
    half.rotation.z = angle;
    half.userData = { age: 0, vx: Math.cos(angle + side * .7) * 1.8, vy: 1.8 + side * .35, spin: side * 2.8 };
    debris.push(half);
    scene.add(half);
  }
  emitParticles(originalPosition, type.inside);
  const now = performance.now();
  comboCount = now - lastSliceTime < 650 ? comboCount + 1 : 1;
  lastSliceTime = now;
  const points = 10 * (comboCount > 1 ? Math.min(comboCount, 5) : 1);
  setScore(score + points);
  if (score > bestScore) {
    bestScore = score;
    try { localStorage.setItem('fruit-best', String(bestScore)); } catch {}
    updateMenuBest();
  }
  if (comboCount > 1) {
    const combo = document.querySelector('#combo');
    combo.textContent = `${comboCount}× COMBO!`;
    combo.classList.remove('hidden');
    void combo.offsetWidth;
    combo.style.animation = 'none';
    void combo.offsetWidth;
    combo.style.animation = '';
    clearTimeout(comboTimer);
    comboTimer = setTimeout(() => combo.classList.add('hidden'), 720);
    playSfx('combo');
  } else playSfx('slice');
}
function missFruit(fruit) {
  removeFruit(fruit);
  lives = Math.max(0, lives - 1);
  updateLives();
  showToast('A fruit slipped away!');
  if (lives <= 0) endGame();
}
function endGame() {
  if (state !== 'playing') return;
  state = 'over';
  document.querySelector('#final-score').textContent = String(score);
  document.querySelector('#final-best').textContent = String(bestScore);
  document.querySelector('#hud').classList.add('hidden');
  hideScreens();
  document.querySelector('#gameover-screen').classList.remove('hidden');
  playSfx('over');
}
function startGame() {
  ensureAudio();
  hideScreens();
  clearObjects(active);
  clearObjects(debris);
  state = 'playing';
  score = 0;
  lives = 3;
  roundTime = 0;
  spawnTimer = .35;
  comboCount = 0;
  setScore(0);
  updateLives();
  document.querySelector('#hud').classList.remove('hidden');
  document.querySelector('#combo').classList.add('hidden');
  document.querySelector('#toast').classList.add('hidden');
}
function pauseGame() {
  if (state !== 'playing') return;
  state = 'paused';
  document.querySelector('#pause-screen').classList.remove('hidden');
}
function resumeGame() {
  if (state !== 'paused') return;
  document.querySelector('#pause-screen').classList.add('hidden');
  state = 'playing';
}
function goMenu() {
  state = 'menu';
  clearObjects(active);
  clearObjects(debris);
  document.querySelector('#hud').classList.add('hidden');
  document.querySelector('#combo').classList.add('hidden');
  hideScreens();
  document.querySelector('#menu-screen').classList.remove('hidden');
  updateMenuBest();
}
function screenPoint(event) {
  const rect = canvas.getBoundingClientRect();
  const x = (event.clientX - rect.left) / rect.width * (camera.right - camera.left) + camera.left;
  const y = camera.top - (event.clientY - rect.top) / rect.height * (camera.top - camera.bottom);
  return new THREE.Vector2(x, y);
}
function addTrail(from, to) {
  const el = document.createElement('i');
  el.className = 'trail';
  const dx = to.clientX - from.clientX;
  const dy = to.clientY - from.clientY;
  el.style.left = `${from.clientX}px`;
  el.style.top = `${from.clientY}px`;
  el.style.width = `${Math.hypot(dx, dy)}px`;
  el.style.transform = `rotate(${Math.atan2(dy, dx)}rad)`;
  document.querySelector('#trail-layer').appendChild(el);
  setTimeout(() => el.remove(), 130);
}
canvas.addEventListener('pointerdown', event => {
  if (state !== 'playing') return;
  pointerDown = true;
  previousPoint = { x: event.clientX, y: event.clientY, world: screenPoint(event) };
  canvas.setPointerCapture?.(event.pointerId);
});
canvas.addEventListener('pointermove', event => {
  if (!pointerDown || state !== 'playing' || !previousPoint) return;
  const point = screenPoint(event);
  addTrail(previousPoint, event);
  const segment = new THREE.Vector2().subVectors(point, previousPoint.world);
  const threshold = .23;
  for (const fruit of [...active]) {
    const pos = fruit.position;
    const toFruit = new THREE.Vector2(pos.x - previousPoint.world.x, pos.y - previousPoint.world.y);
    const along = THREE.MathUtils.clamp(toFruit.dot(segment) / Math.max(segment.lengthSq(), .0001), 0, 1);
    const distance = toFruit.distanceTo(segment.clone().multiplyScalar(along));
    if (distance < threshold + fruit.userData.radius * .43) splitFruit(fruit, segment);
  }
  previousPoint = { x: event.clientX, y: event.clientY, world: point };
});
function releasePointer() { pointerDown = false; previousPoint = null; }
canvas.addEventListener('pointerup', releasePointer);
canvas.addEventListener('pointercancel', releasePointer);

// Audio is synthesized locally, so the game needs no external sound assets.
let audio = null;
let musicTimer = null;
let musicStep = 0;
function loadSettings() {
  const defaults = { master: .72, sfx: .75, music: .38, brightness: 1, musicOn: true, muted: false };
  try { return { ...defaults, ...JSON.parse(localStorage.getItem('fruit-settings') || '{}') }; }
  catch { return defaults; }
}
const audioSettings = loadSettings();
function saveSettings() { try { localStorage.setItem('fruit-settings', JSON.stringify(audioSettings)); } catch {} }
function ensureAudio() {
  if (!audio) {
    const Context = window.AudioContext || window.webkitAudioContext;
    if (!Context) return;
    audio = new Context();
  }
  if (audio.state === 'suspended') audio.resume();
  if (audioSettings.musicOn && !musicTimer) startMusic();
}
function volume(kind) { return (audioSettings.muted ? 0 : audioSettings.master) * (kind === 'music' ? audioSettings.music : audioSettings.sfx); }
function tone(freq, duration, wave = 'sine', gain = .08, delay = 0) {
  if (!audio) return;
  const now = audio.currentTime + delay;
  const osc = audio.createOscillator();
  const amp = audio.createGain();
  osc.type = wave;
  osc.frequency.setValueAtTime(freq, now);
  amp.gain.setValueAtTime(.0001, now);
  amp.gain.exponentialRampToValueAtTime(Math.max(.0002, gain * volume('sfx')), now + .012);
  amp.gain.exponentialRampToValueAtTime(.0001, now + duration);
  osc.connect(amp); amp.connect(audio.destination);
  osc.start(now); osc.stop(now + duration + .03);
}
function playSfx(kind) {
  if (!audio) return;
  if (kind === 'tap') tone(620, .07, 'sine', .04);
  else if (kind === 'launch') tone(310, .09, 'triangle', .025);
  else if (kind === 'slice') { tone(850, .08, 'sawtooth', .045); tone(1250, .12, 'sine', .03, .025); }
  else if (kind === 'combo') { tone(660, .13, 'triangle', .06); tone(990, .2, 'triangle', .05, .09); }
  else if (kind === 'over') { tone(400, .2, 'triangle', .05); tone(300, .32, 'triangle', .04, .18); }
  else if (kind === 'score') tone(740, .1, 'sine', .04);
}
const melody = [523, 659, 784, 659, 587, 698, 880, 698, 523, 659, 784, 988, 880, 784, 659, 587];
function startMusic() {
  if (!audio || musicTimer || !audioSettings.musicOn) return;
  musicTimer = setInterval(() => {
    const now = audio.currentTime;
    const osc = audio.createOscillator();
    const gain = audio.createGain();
    osc.type = 'sine';
    osc.frequency.value = melody[musicStep++ % melody.length];
    gain.gain.setValueAtTime(.0001, now);
    gain.gain.exponentialRampToValueAtTime(Math.max(.0001, .025 * volume('music')), now + .08);
    gain.gain.exponentialRampToValueAtTime(.0001, now + .36);
    osc.connect(gain); gain.connect(audio.destination);
    osc.start(now); osc.stop(now + .38);
  }, 330);
}
function stopMusic() { if (musicTimer) { clearInterval(musicTimer); musicTimer = null; } }
function syncSettingsUI() {
  for (const [id, key] of [['master-volume', 'master'], ['sfx-volume', 'sfx'], ['music-volume', 'music'], ['brightness', 'brightness']]) document.getElementById(id).value = audioSettings[key];
  for (const [id, key] of [['master-value', 'master'], ['sfx-value', 'sfx'], ['music-value', 'music']]) document.getElementById(id).textContent = `${Math.round(audioSettings[key] * 100)}%`;
  document.getElementById('brightness-value').textContent = `${Math.round(audioSettings.brightness * 100)}%`;
  document.querySelector('#music-switch span').textContent = audioSettings.musicOn ? 'ON' : 'OFF';
  document.querySelector('#sound-toggle').textContent = audioSettings.muted ? '♫̸' : '♫';
  brightness = audioSettings.brightness;
  scene.traverse(object => {
    if (!object.material) return;
    const mats = Array.isArray(object.material) ? object.material : [object.material];
    for (const mat of mats) if (mat.userData.baseColor) mat.color.copy(mat.userData.baseColor).multiplyScalar(brightness);
  });
}
for (const [id, key] of [['master-volume', 'master'], ['sfx-volume', 'sfx'], ['music-volume', 'music'], ['brightness', 'brightness']]) {
  document.getElementById(id).addEventListener('input', event => { audioSettings[key] = Number(event.target.value); saveSettings(); syncSettingsUI(); });
}
document.querySelector('#music-switch').addEventListener('click', () => {
  audioSettings.musicOn = !audioSettings.musicOn;
  if (audioSettings.musicOn) { ensureAudio(); startMusic(); } else stopMusic();
  saveSettings(); syncSettingsUI(); playSfx('tap');
});
document.querySelector('#sound-toggle').addEventListener('click', () => {
  audioSettings.muted = !audioSettings.muted;
  saveSettings(); syncSettingsUI();
  if (!audioSettings.muted) { ensureAudio(); playSfx('tap'); }
});
function clickSound() { ensureAudio(); playSfx('tap'); }
document.querySelector('#play-button').addEventListener('click', startGame);
document.querySelector('#settings-button').addEventListener('click', () => { clickSound(); hideScreens(); document.querySelector('#settings-screen').classList.remove('hidden'); syncSettingsUI(); });
document.querySelector('#credits-button').addEventListener('click', () => { clickSound(); hideScreens(); document.querySelector('#credits-screen').classList.remove('hidden'); });
document.querySelectorAll('[data-back]').forEach(button => button.addEventListener('click', () => { clickSound(); hideScreens(); document.getElementById(button.dataset.back).classList.remove('hidden'); }));
document.querySelectorAll('[data-menu]').forEach(button => button.addEventListener('click', () => { clickSound(); goMenu(); }));
document.querySelector('#pause-button').addEventListener('click', () => { playSfx('tap'); pauseGame(); });
document.querySelector('#resume-button').addEventListener('click', () => { playSfx('tap'); resumeGame(); });
document.querySelector('#restart-button').addEventListener('click', startGame);
document.querySelector('#again-button').addEventListener('click', startGame);
document.addEventListener('visibilitychange', () => { if (document.hidden && state === 'playing') pauseGame(); });
syncSettingsUI();
loadBest();
updateMenuBest();

let lastTime = performance.now();
function animate(now) {
  requestAnimationFrame(animate);
  const dt = Math.min(.035, (now - lastTime) / 1000);
  lastTime = now;
  const elapsed = now / 1000;
  if (state === 'playing') {
    roundTime += dt;
    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawnWave();
      spawnTimer = Math.max(.72, 1.65 - roundTime * .009 - score * .0008) + Math.random() * .38;
    }
    for (const fruit of [...active]) {
      const data = fruit.userData;
      data.age += dt;
      data.velocity.y -= 9.5 * dt;
      fruit.position.addScaledVector(data.velocity, dt);
      fruit.rotation.z += data.spin * dt;
      fruit.rotation.x += dt * .32;
      if (fruit.position.y < -6.5) missFruit(fruit);
    }
  }
  for (const glow of decor) {
    glow.position.y += Math.sin(elapsed * .7 + glow.userData.index) * dt * .32;
    glow.position.x += Math.cos(elapsed * .45 + glow.userData.index) * dt * .15;
  }
  for (let i = debris.length - 1; i >= 0; i--) {
    const object = debris[i];
    const data = object.userData;
    if (data.life !== undefined) {
      data.life -= dt;
      data.vy -= 5 * dt;
      object.position.x += data.vx * dt;
      object.position.y += data.vy * dt;
      object.scale.multiplyScalar(Math.max(.01, 1 - dt * 1.1));
      if (data.life <= 0) { scene.remove(object); debris.splice(i, 1); }
    } else {
      data.age += dt;
      data.vy -= 8.8 * dt;
      object.position.x += data.vx * dt;
      object.position.y += data.vy * dt;
      object.rotation.z += data.spin * dt;
      if (data.age > 1.8 || object.position.y < -7) { scene.remove(object); debris.splice(i, 1); }
    }
  }
  renderer.render(scene, camera);
}
requestAnimationFrame(animate);

